arguments.content:
const columns = [
  {
    title: 'Todo',
    tasks: [
      { title: 'Map onboarding flow', assignee: 'Maya Chen', priority: 'High' },
      { title: 'Draft release notes', assignee: 'Owen Brooks', priority: 'Medium' },
    ],
  },
  {
    title: 'In Progress',
    tasks: [
      { title: 'Build analytics cards', assignee: 'Priya Shah', priority: 'High' },
      { title: 'QA mobile navigation', assignee: 'Leo Martin', priority: 'Low' },
    ],
  },
  {
    title: 'Done',
    tasks: [
      { title: 'Finalize brand palette', assignee: 'Ava Wilson', priority: 'Medium' },
      { title: 'Set up team retro', assignee: 'Noah Kim', priority: 'Low' },
    ],
  },
]

const priorityClass = {
  High: 'priority-high',
  Medium: 'priority-medium',
  Low: 'priority-low',
}

export default function App() {
  return (
    <main className="app-shell">
      <section className="topbar">
        <div>
          <p className="eyebrow">Sprint 14</p>
          <h1>Orbit</h1>
        </div>
        <button className="add-button" type="button">+ Add task</button>
      </section>

      <section className="board" aria-label="Orbit sprint task board">
        {columns.map((column) => (
          <article className="column" key={column.title}>
            <header className="column-header">
              <h2>{column.title}</h2>
              <span>{column.tasks.length}</span>
            </header>
            <div className="task-list">
              {column.tasks.map((task) => (
                <div className="task-card" key={task.title}>
                  <div className="card-topline">
                    <span className={`priority ${priorityClass[task.priority]}`}>{task.priority}</span>
                  </div>
                  <h3>{task.title}</h3>
                  <p>{task.assignee}</p>
                </div>
              ))}
            </div>
          </article>
        ))}
      </section>
    </main>
  )
}

:root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #172033;
  background: #f6f8fb;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background:
    radial-gradient(circle at top left, rgba(106, 139, 255, 0.14), transparent 34rem),
    linear-gradient(180deg, #fbfcff 0%, #eef3f9 100%);
}

button {
  font: inherit;
}

.app-shell {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
  padding: 44px 0;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
}

.eyebrow {
  margin: 0 0 6px;
  color: #68748a;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: clamp(40px, 6vw, 64px);
  line-height: 0.95;
  letter-spacing: -0.06em;
}

.add-button {
  border: 0;
  border-radius: 999px;
  background: #3158f5;
  color: white;
  cursor: pointer;
  box-shadow: 0 16px 30px rgba(49, 88, 245, 0.22);
  font-weight: 800;
  padding: 14px 22px;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
  white-space: nowrap;
}

.add-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 20px 36px rgba(49, 88, 245, 0.28);
}

.board {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.column {
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid rgba(203, 212, 227, 0.8);
  border-radius: 28px;
  box-shadow: 0 20px 55px rgba(34, 48, 74, 0.08);
  padding: 18px;
  min-height: 540px;
}

.column-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 4px 16px;
}

.column-header h2 {
  margin: 0;
  font-size: 20px;
  letter-spacing: -0.02em;
}

.column-header span {
  display: inline-grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #edf2f8;
  color: #627089;
  font-weight: 800;
}

.task-list {
  display: grid;
  gap: 14px;
}

.task-card {
  background: #ffffff;
  border: 1px solid #e7ecf3;
  border-radius: 22px;
  padding: 18px;
  box-shadow: 0 12px 26px rgba(24, 39, 66, 0.07);
}

.card-topline {
  display: flex;
  justify-content: flex-start;
  margin-bottom: 18px;
}

.priority {
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
  line-height: 1;
  padding: 8px 10px;
}

.priority-high {
  color: #9f2d31;
  background: #ffe8e9;
}

.priority-medium {
  color: #92620f;
  background: #fff2d6;
}

.priority-low {
  color: #19735c;
  background: #ddf8ee;
}

.task-card h3 {
  margin: 0 0 14px;
  color: #202b3e;
  font-size: 18px;
  line-height: 1.25;
  letter-spacing: -0.02em;
}

.task-card p {
  margin: 0;
  color: #66738a;
  font-size: 14px;
  font-weight: 700;
}

@media (max-width: 820px) {
  .topbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .board {
    grid-template-columns: 1fr;
  }

  .column {
    min-height: auto;
  }
}

