  line-height: 1;
  padding: 8px 10px;
}

.priority-high {
  color: #9f2d31;
  background: #ffe8e9;
}

.priority-medium {
  color: #92620f;
  background: #fff2d6;
}

.priority-low {
  color: #19735c;
  background: #ddf8ee;
}

.task-card h3 {
  margin: 0 0 14px;
  color: #202b3e;
  font-size: 18px;
  line-height: 1.25;
  letter-spacing: -0.02em;
}

.task-card p {
  margin: 0;
  color: #66738a;
  font-size: 14px;
  font-weight: 700;
}

